<?php
require_once __DIR__ . '/config/config.php';
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/config/customer-auth.php';
require_once __DIR__ . '/includes/promotions.php';
$pdo=db(); if($pdo){ try{ customer_auth_init($pdo); ensure_promotions_tables($pdo);}catch(Throwable $e){} }
$isMember=customer_logged_in();
$promos=[]; $vouchers=[];
if($pdo){
    $stmt=$pdo->query("SELECT * FROM promotions WHERE status='active' AND starts_at<=NOW() AND ends_at>=NOW() ORDER BY ends_at ASC, id DESC");
    foreach($stmt->fetchAll() as $r){ if((int)$r['member_only']===1 && !$isMember) continue; $promos[]=$r; }
    $stmt=$pdo->query("SELECT * FROM vouchers WHERE status='active' AND starts_at<=NOW() AND ends_at>=NOW() ORDER BY ends_at ASC, id DESC");
    foreach($stmt->fetchAll() as $r){ if((int)$r['member_only']===1 && !$isMember) continue; $vouchers[]=$r; }
}
include __DIR__ . '/includes/header.php'; ?>
<header class="main-header"><?php include __DIR__ . '/includes/topbar.php'; ?><?php include __DIR__ . '/includes/navbar.php'; ?></header>
<main class="promo-page"><div class="container">
<div class="catalog-breadcrumb detail-breadcrumb"><a href="<?php echo page_url('index.php'); ?>">Home</a><i class="bi bi-chevron-right"></i><span>Promo Member</span></div>
<section class="promo-hero"><span class="small-title">PROMO & VOUCHER</span><h1>Keuntungan <span>Member</span> Rosa Indah Printing</h1><p>Dapatkan informasi promo, voucher, dan diskon khusus Member sebelum checkout.</p><?php if(!$isMember): ?><div class="promo-login-note"><i class="bi bi-lock-fill"></i><span>Promo khusus Member hanya dapat digunakan setelah Anda login.</span><a class="catalog-primary-btn" href="<?php echo page_url('login.php'); ?>">Login Member</a><a class="catalog-secondary-btn" href="<?php echo page_url('daftar.php'); ?>">Daftar Member</a></div><?php else: ?><div class="promo-member-ok"><i class="bi bi-patch-check-fill"></i> Anda login sebagai Member. Selamat menikmati promo yang tersedia!</div><?php endif; ?></section>
<section class="promo-section"><div class="catalog-heading"><div><span class="small-title">PROMO AKTIF</span><h2>Diskon Otomatis</h2></div></div><div class="promo-grid"><?php if(!$promos): ?><div class="promo-empty">Belum ada promo aktif yang sesuai untuk Anda.</div><?php else: foreach($promos as $r): ?><article class="promo-card"><div class="promo-icon"><i class="bi bi-stars"></i></div><div><span class="promo-badge"><?php echo htmlspecialchars(promo_label($r)); ?></span><h3><?php echo htmlspecialchars($r['name']); ?></h3><p><?php echo htmlspecialchars($r['description'] ?: 'Promo otomatis akan diterapkan saat checkout jika semua syarat terpenuhi.'); ?></p><small><?php echo htmlspecialchars(promo_scope_label($r)); ?> · Min. Rp<?php echo number_format((float)$r['min_order'],0,',','.'); ?></small><small>Berlaku sampai <?php echo htmlspecialchars(promo_format_date($r['ends_at'])); ?></small></div></article><?php endforeach; endif; ?></div></section>
<section class="promo-section"><div class="catalog-heading"><div><span class="small-title">KODE VOUCHER</span><h2>Voucher yang Bisa Dipakai</h2></div></div><div class="voucher-grid"><?php if(!$vouchers): ?><div class="promo-empty">Belum ada voucher aktif yang sesuai untuk Anda.</div><?php else: foreach($vouchers as $r): ?><article class="voucher-card"><div class="voucher-cut"></div><div><span class="voucher-code"><?php echo htmlspecialchars($r['code']); ?></span><h3><?php echo htmlspecialchars($r['name']); ?></h3><strong><?php echo htmlspecialchars(promo_label($r)); ?></strong><p><?php echo htmlspecialchars($r['description'] ?: 'Masukkan kode ini di checkout.'); ?></p><small>Min. Rp<?php echo number_format((float)$r['min_order'],0,',','.'); ?> · <?php echo htmlspecialchars(promo_scope_label($r)); ?></small><small>Berlaku sampai <?php echo htmlspecialchars(promo_format_date($r['ends_at'])); ?></small></div></article><?php endforeach; endif; ?></div></section>
